var day = get_tree().get_first_node_in_group('day_cycle')
var fog = get_tree().get_first_node_in_group('fog_event')
var player = get_tree().get_first_node_in_group('player')
var stats_n = get_tree().get_first_node_in_group('player_stats')
var lantern = get_tree().get_first_node_in_group('lantern')
return {
	'day': day.current_day if day else -1,
	'clock': day.clock_text() if day else '',
	'time': day.time_of_day if day else -1,
	'night': day.is_night if day else false,
	'fog': fog.state if fog else -1,
	'cycle': fog.fog_cycle if fog else -1,
	'safe': fog.player_is_safe if fog else null,
	'hp': stats_n.health if stats_n else -1,
	'lantern_r': lantern.get_safe_radius_tiles() if lantern else -1,
	'dx': ((player.global_position - lantern.global_position).length() / 16.0) if player and lantern else -1
}
